function UICatFilterMB:RefreshUI()
    local sortTypeData = self.sortTypeList[self.selectIndex]
    self:RefreshAlignNode(sortTypeData)
    --if self.ImgArrow then
    --    self.ImgArrow.localEulerAngles = Vector3.New(0, 0, -90)
    --end
    ---如果是对卡牌等级排序
    if self.callback ~= nil then
        local sortTypeId = sortTypeData.sortTypeId
        self.callback(sortTypeId)
    end
    KTool.SetActive(self.AlignDropDown.gameObject, false)

end


